import sys

def calculate_unavailability(N, arrival_times):
    def get_next_bridge_time(bridge_time, next_arrival):
        return max(bridge_time, next_arrival) + 20

    def get_total_unavailability(arrival_times):
        unavailability = 0
        current_bridge_time = 0

        for arrival in arrival_times:
            if arrival > current_bridge_time:
                unavailability += get_next_bridge_time(current_bridge_time, arrival)
                current_bridge_time = get_next_bridge_time(current_bridge_time, arrival) + 60
            else:
                current_bridge_time += 20

        return unavailability

    return get_total_unavailability(arrival_times)

