from sys import stdin, stdout

def main():
    n = int(stdin.readline())
    times = [int(stdin.readline()) for _ in range(n)]

    end_time = 0
    total_unavailable_time = 0

    for t in times:
        if t > end_time:
            total_unavailable_time += (t - end_time)
        end_time = max(end_time, t) + 60 + 20

    stdout.write(str(total_unavailable_time))

if __name__ == "__main__":
    main()
